const TEST_RE = [
  /^test_.*\.py$/, /^test_.*\.mjs$/, /^test_.*\.js$/, /^test_.*\.ts$/,
  /.*_test\.py$/, /.*\.test\.ts$/, /.*\.test\.js$/, /.*\.test\.mjs$/
]
const isTestFile = (p) => {
  const base = p.split('/').pop()
  return TEST_RE.some((re) => re.test(base))
}
const stem = (p) => {
  const base = p.split('/').pop()
  const i = base.lastIndexOf('.')
  return i > 0 ? base.slice(0, i) : base
}
function needlesFrom (paths, symbols) {
  const out = []
  for (const p of paths) {
    if (isTestFile(p)) continue
    out.push(p, stem(p))
  }
  for (const s of symbols) out.push(s)
  const seen = new Set()
  const result = []
  for (const n of out) {
    if (n.length < 4) continue
    if (seen.has(n)) continue
    seen.add(n)
    result.push(n)
  }
  return result
}
function matches (needle, text) {
  if (needle.includes('/') || needle.includes('.')) return text.includes(needle)
  const re = new RegExp(`(?<![A-Za-z0-9_$])${needle.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}(?![A-Za-z0-9_$])`)
  return re.test(text)
}
export async function candidateTests ({ files, read, paths, symbols, exclude = [], cap = 8 }) {
  const needles = needlesFrom(paths, symbols)
  const excludeSet = new Set(exclude)
  const results = []
  for (const p of files) {
    if (!isTestFile(p)) continue
    if (excludeSet.has(p)) continue
    const text = await read(p)
    const hits = needles.filter((n) => matches(n, text))
    if (hits.length) results.push({ path: p, hits })
  }
  results.sort((a, b) => b.hits.length - a.hits.length || (a.path < b.path ? -1 : a.path > b.path ? 1 : 0))
  return results.slice(0, cap)
}
export function symbolsOf (clauses) {
  const out = []
  const seen = new Set()
  for (const c of clauses) {
    const spans = c.match(/`([^`]*)`/g) || []
    for (const raw of spans) {
      const span = raw.slice(1, -1)
      let value
      if (span.includes('/') && /\.[A-Za-z0-9]+$/.test(span)) value = span
      else {
        const m = span.match(/^[A-Za-z_$][A-Za-z0-9_$]*/)
        value = m ? m[0] : ''
      }
      if (value.length < 4) continue
      if (seen.has(value)) continue
      seen.add(value)
      out.push(value)
    }
  }
  return out
}
export function commandFor (path, seconds) {
  if (path.endsWith('.test.ts')) return ['timeout', String(seconds), 'bun', 'test', path]
  if (path.endsWith('.py')) return ['timeout', String(seconds), 'python3', '-m', 'pytest', '-q', path]
  if (path.endsWith('.mjs') || path.endsWith('.js')) return ['timeout', String(seconds), 'node', path]
  return null
}
